    "v19": "sched_link_count",
    "v21": "new_sched_link_count",
    "v22": "old_sched_ctxt",
    "v24": "vif_table_end"
  },
  "struct_hints": [
    {
      "offset": 24,
      "meaning": "channel context validity/state byte; 0xFF appears to mark an unlinked or invalid entry"
    },
    {
      "offset": 25,
      "meaning": "channel context link/reference count"
    },
    {
      "offset": 16,
      "meaning": "channel context active/link-added flag"
    },
    {
      "offset": 72,
      "meaning": "VIF context field holding the linked channel-context pointer"
    },
    {
      "offset": 85,
      "meaning": "VIF context channel/link flag byte or bitfield"
    },
    {
      "offset": 1224,
      "meaning": "VIF context current channel/link state byte"
    },
    {
      "offset": 1225,
      "meaning": "VIF context byte used as an index into an associated STA/context table"
    }
  ]
}
